def iDBSDcollTemplate(input1, input2, input3, input4, input5):
	import mpp
	import os

	resultImage = input1
	resultData = input2
	globalItems = input5


	########### fixed ###########
	id = globalItems['gs_defectid']
	imageFileName = str(id) + '_result.jpg'
	imageFilePath = os.path.join(globalItems['gs_resultimageurl'].strip(),imageFileName)
	dcollFilePath = os.path.join(globalItems['gs_resultdataurl'].strip(),str(id) + '_DColl.csv')

	########## DAQ Result ############
	summaryFilePath = os.path.join(globalItems['gs_resultdataurl'].strip(),str(id) + '_Summary.csv')
	defectFilePath = os.path.join(globalItems['gs_resultdataurl'].strip(),str(id) + '_Defect.csv')

	#### Header
	summaryData = list()
	summaryData.append(['WAFERID','DEFECTID','DIEX','DIEY','XREAL','YREAL','IMAGEWIDTH','IMAGEHEIGHT','ALIGNMENT','MEASUREMENT','DEFECT','EXTENSIONFUNC','RELATIVEPATH','PATH','GDSX','GDSY'])
	summaryData.append([globalItems['gs_waferid'],globalItems['gs_defectid'],globalItems['gs_xindex'],globalItems['gs_yindex'],globalItems['gs_xreal'],globalItems['gs_yreal'],'0','0','OK','OK','OK','OK',imageFileName,imageFilePath,'0','0'])


	#### Save summaryData
	mpp.intel64.save_csv(summaryData, summaryFilePath)

	#### Save defect
	mpp.intel64.save_csv(summaryData, defectFilePath)

	#### Save Result image
	mpp.intel64.save(resultImage, imageFilePath)

	#### Header
	dcollData = list()
	dcollData.append(['ID','TYPE','NAME','VALUE','DESCRIPTION'])

	#### image Data
	dcollData.append([id, 'IMG', 'PATH', imageFilePath, 'Result Image'])

	#### Defect ID
	dcollData.append([id, 'IDBS', 'DEFECTID', id, 'DefectID'])

	#### iDBS Data
	dcollData.append([id, 'IDBS', 'CD1', float(resultData['port_1']['roi_1']['MAJOR']['value']), 'CD1'])
	dcollData.append([id, 'IDBS', 'CD2', float(resultData['port_1']['roi_1']['MINOR']['value']), 'CD2'])
	dcollData.append([id, 'IDBS', 'CD3', float(resultData['port_1']['roi_1']['MIN']['value']), 'CD3'])
	dcollData.append([id, 'IDBS', 'CD4', float(resultData['port_1']['roi_2']['MAJOR']['value']), 'CD4'])
	dcollData.append([id, 'IDBS', 'CD5', float(resultData['port_1']['roi_2']['MINOR']['value']), 'CD5'])
	dcollData.append([id, 'IDBS', 'CD6', float(resultData['port_1']['roi_2']['MIN']['value']), 'CD6'])
	dcollData.append([id, 'IDBS', 'CD7', float(resultData['port_1']['roi_3']['MAJOR']['value']), 'CD7'])
	dcollData.append([id, 'IDBS', 'CD8', float(resultData['port_1']['roi_3']['MINOR']['value']), 'CD8'])
	dcollData.append([id, 'IDBS', 'CD10', float(resultData['port_1']['roi_3']['MIN']['value']), 'CD9'])
	dcollData.append([id, 'IDBS', 'CD11', float(resultData['port_1']['roi_4']['MAJOR']['value']), 'CD10'])
	dcollData.append([id, 'IDBS', 'CD12', float(resultData['port_1']['roi_4']['MINOR']['value']), 'CD11'])
	dcollData.append([id, 'IDBS', 'CD13', float(resultData['port_1']['roi_4']['MIN']['value']), 'CD12'])
	
	#### Save DcollData
	mpp.intel64.save_csv(dcollData, dcollFilePath)

	return resultImage, None, None, None, None



def CustomFunction3(input1, input2, input3):
	output1 = input1
	output2 = input2
	output3 = input3
	import json
	
	roi_dict = dict()
	for key in input1:
		roi_dict[key] = json.dumps(input1[key])
	
	return roi_dict, output2, output3

